/* ============================================
   NAV LIST COMPONENT
   Vertical navigation link list for drawers and
   side menus. Rows are tertiary Buttons — their
   shape, sizing, and states live in Button.css;
   this file owns only layout, the chevron
   toggle, and the expand animation.
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-nav-list {
  /* How far a row's text sits in from the row's own edge (the rows are
     compact tertiary Buttons, the headings share their inset). A host that
     lines the list's text up with something above it, a header's brand,
     hangs the list out by this much, so the fills sit in the gutter and the
     words sit on the line (SiteLayout's sidebar does). Compact rows inset
     their text --padding-300; default rows (a default Button) --padding-500,
     set below. */
  --ds-nav-list-text-inset: var(--padding-300);
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Every row reserves the toggle's 40px height, so leaf rows (compact
   Buttons, ~32px) and rows carrying a 40px chevron toggle sit on the same
   vertical rhythm instead of producing uneven gaps down the list. */
.ds-nav-list__item {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 40px;
}

/* ============================================
   ROWS
   Full-width, left-aligned Buttons; long labels
   truncate with an ellipsis.
   ============================================ */

.ds-nav-list .ds-button {
  width: 100%;
  max-width: 100%;
  justify-content: flex-start;
  text-align: start;
}

.ds-nav-list .ds-button__text {
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A row with a toggle shares its width with the chevron button. */
.ds-nav-list__row {
  display: flex;
  align-items: center;
  gap: var(--gap-050);
  width: 100%;
}

.ds-nav-list__row .ds-button {
  width: auto;
  flex: 1 1 auto;
  min-width: 0;
}

/* ============================================
   TOGGLE
   Mirrors IconButton's 40px tertiary recipe.
   ============================================ */

.ds-nav-list__toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background-color: var(--color-action-passive-bg);
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-nav-list__toggle:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-nav-list__toggle:active {
  background-color: var(--color-action-passive-bg-active);
}

.ds-nav-list__toggle:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-nav-list__chevron {
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
  line-height: 1;
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-nav-list__toggle[aria-expanded='true'] .ds-nav-list__chevron {
  transform: rotate(180deg);
}

/* ============================================
   PANEL — collapsible sublist wrapper
   Grid-rows height animation; reduced motion is
   handled by the motion-token contract.
   ============================================ */

.ds-nav-list__panel {
  display: grid;
  grid-template-rows: 0fr;
  margin-top: 0;
  transition:
    grid-template-rows var(--motion-duration-slow) var(--motion-ease-emphasized),
    margin-top var(--motion-duration-slow) var(--motion-ease-emphasized);
}

/* Open panels take the list's item gap above them, so the first child sits
   the same distance from its parent row as any two siblings do. */
.ds-nav-list__panel--open {
  grid-template-rows: 1fr;
  margin-top: var(--gap-050);
}

/* ============================================
   SUBLIST — one indent step per nesting level
   ============================================ */

.ds-nav-list__sublist {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  overflow: hidden;
  min-height: 0;
  margin: 0;
  padding: 0;
  padding-inline-start: var(--padding-1000);
  list-style: none;
}

.ds-nav-list__sublist .ds-nav-list__sublist {
  padding-inline-start: var(--gap-500);
}

/* Permanent (non-collapsible) groups render their sublist directly under the
   row, with no panel — give it the same item gap the panel carries when open. */
.ds-nav-list__item > .ds-nav-list__sublist {
  margin-top: var(--gap-050);
}

/* ============================================
   COMPACT
   Every row on the 32px compact control height, for a
   long sidebar: the 40px reservation and toggle step down
   to match, so a hundred rows read as one quiet column.
   ============================================ */

/* Default size: the top-level rows are default Buttons, so their text sits
   --padding-500 in; the hang and the section headings follow it, so the
   headings sit on the rows' leading line at either size. */
.ds-nav-list:not(.ds-nav-list--compact) {
  --ds-nav-list-text-inset: var(--padding-500);
}

.ds-nav-list:not(.ds-nav-list--compact) .ds-nav-list__heading {
  padding-inline-start: var(--padding-500);
}

.ds-nav-list--compact .ds-nav-list__item {
  min-height: var(--control-height-compact);
}

.ds-nav-list--compact .ds-nav-list__toggle {
  width: var(--control-height-compact);
  height: var(--control-height-compact);
}

.ds-nav-list--compact .ds-nav-list__sublist {
  padding-inline-start: var(--padding-400);
}

.ds-nav-list__badge {
  margin-inline-start: auto;
}

/* ============================================
   SECTIONS
   A heading over its rows: the rails' group heading
   (caption face, tertiary text, mixed case), seated on
   the rows' leading line. A collapsible heading is a
   full-width quiet button with the chevron at its end.
   ============================================ */

.ds-nav-list__section {
  display: flex;
  flex-direction: column;
}

.ds-nav-list__section + .ds-nav-list__section,
.ds-nav-list__item + .ds-nav-list__section {
  margin-block-start: var(--gap-500);
}

.ds-nav-list__heading {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  box-sizing: border-box;
  min-height: var(--control-height-compact);
  padding-inline: var(--padding-300);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
}

.ds-nav-list--compact .ds-nav-list__heading {
  padding-inline: var(--padding-300);
}

.ds-nav-list__heading--toggle {
  width: 100%;
  margin: 0;
  padding-inline-end: var(--padding-200);
  border: none;
  border-radius: var(--radius-pill);
  background: none;
  text-align: start;
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-nav-list__heading--toggle:hover {
  background-color: var(--color-action-passive-bg-hover);
  color: var(--color-text-secondary);
}

.ds-nav-list__heading--toggle:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-nav-list__heading-text {
  flex: 1 1 auto;
  min-width: 0;
}

.ds-nav-list__heading--toggle[aria-expanded='true'] .ds-nav-list__chevron {
  transform: rotate(180deg);
}

.ds-nav-list__section-list {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
  overflow: hidden;
  min-height: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ============================================
   SCROLLABLE
   The list as its own scroll area: it takes its parent's
   height, keeps its scroll to itself at both ends, and
   keeps a still gutter so rows do not shift when the
   scrollbar comes and goes.
   ============================================ */

.ds-nav-list--scrollable {
  /* How far the content fades in or out at an end with more to scroll. */
  --ds-nav-list-fade: var(--gap-1000);
  --ds-nav-list-fade-start: 0px;
  --ds-nav-list-fade-end: 0px;
  flex-wrap: nowrap;
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  /* Room at both ends for the fade, a hook so a host can line the first
     row up with something beside it (SiteLayout's sidebar pulls the list up
     by it, so the first row starts level with the page's first line). */
  --ds-nav-list-block-inset: var(--padding-200);
  padding-block: var(--ds-nav-list-block-inset);
  /* The scrollbar stays out of sight until the list scrolls. */
  scrollbar-width: none;
  /* The ends fade only when there is more past them, so a list at its top
     shows its first row crisp. ds-allow(color): mask alpha keywords
     (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent,
    black var(--ds-nav-list-fade-start),
    black calc(100% - var(--ds-nav-list-fade-end)),
    transparent
  );
  mask-image: linear-gradient(
    to bottom,
    transparent,
    black var(--ds-nav-list-fade-start),
    black calc(100% - var(--ds-nav-list-fade-end)),
    transparent
  );
}

/* A fixed-height column scrolls its rows rather than squeezing them: a
   flex child would otherwise shrink to fit and the rows would overlap. */
.ds-nav-list--scrollable > * {
  flex-shrink: 0;
}

.ds-nav-list--scrollable[data-fade-start] {
  --ds-nav-list-fade-start: var(--ds-nav-list-fade);
}

.ds-nav-list--scrollable[data-fade-end] {
  --ds-nav-list-fade-end: var(--ds-nav-list-fade);
}

.ds-nav-list--scrollable::-webkit-scrollbar {
  width: 0;
}

/* While it scrolls: a thin thumb on no track, gone again once it settles. */
.ds-nav-list--scrollable[data-scrolling] {
  scrollbar-width: thin;
  scrollbar-color: var(--color-bg-container-border) transparent;
}

.ds-nav-list--scrollable[data-scrolling]::-webkit-scrollbar {
  width: var(--padding-150);
}

.ds-nav-list--scrollable[data-scrolling]::-webkit-scrollbar-thumb {
  border-radius: var(--radius-pill);
  background: var(--color-bg-container-border);
}

} /* @layer rift.components */

'use client';

import React, { useEffect, useId, useRef, useState } from 'react';
import { Button } from '../Button/Button';
import { Badge } from '../Badge/Badge';
import { MOTION_SCROLL_SETTLE_MS } from '../../tokens/motion';
import type { LinkComponent } from '../../behaviors/LinkProvider';
import './NavList.css';
import '../../fonts/material-symbols.css';

export interface NavListItem {
  /** Row text. */
  label: string;
  /** Link destination — every row is a real link. */
  href: string;
  /** Stable identity for expansion state and aria wiring. Defaults to `href`. */
  id?: string;
  /** Child rows, indented one level. Nesting is supported three levels deep. */
  items?: NavListItem[];
  /**
   * When false, an item with children renders no toggle and its children stay
   * visible — a permanent group rather than a collapsible section.
   * @default true
   */
  collapsible?: boolean;
  /**
   * Forces the current-page treatment on this row regardless of the exact
   * match against `currentHref` — for prefix-matched sections that should
   * stay current on their child routes.
   */
  current?: boolean;
  /** A short tag after the label, such as "New" or "Beta", drawn as a neutral Badge. */
  badge?: string;
}

/**
 * A titled section of rows: a heading over its items, the way a long
 * documentation sidebar groups its pages. Sections sit only at the top
 * level; their items nest like any others.
 */
export interface NavListSection {
  /** Marks the entry as a section rather than a row. */
  type: 'section';
  /** The section's heading. */
  label: string;
  /** The section's rows. */
  items: NavListItem[];
  /**
   * Stable identity for its expansion state. Defaults to the label. In
   * `expandedIds`, `defaultExpandedIds` and `onExpandedChange` a section
   * appears as `section:<id>`, so its id never collides with a row's.
   */
  id?: string;
  /**
   * Let the reader fold the section under its heading. Unlike a row with
   * `items`, which folds unless told not to, a section is a plain label
   * unless told to fold.
   * @default false
   */
  collapsible?: boolean;
}

/** A top-level entry: a row, or a section of rows. */
export type NavListEntry = NavListItem | NavListSection;

const isSection = (entry: NavListEntry): entry is NavListSection => (entry as NavListSection).type === 'section';

/** Props owned by NavList itself — everything else falls through to the list element. */
type NavListOwnProps = {
  /** Navigation tree to render: rows, and at the top level, sections of rows. */
  items: NavListEntry[];
  /**
   * Row density. `default` is the drawer's 40px top row; `compact` sets
   * every row on the 32px compact control height, for a long sidebar of
   * pages (a documentation site's hundred entries).
   */
  size?: 'default' | 'compact';
  /**
   * Make the list its own scroll area: it fills the height its parent
   * gives it, scrolls inside without carrying the page along at its ends,
   * and brings the current row into view when it first renders. Put it in
   * a column with a fixed or sticky height.
   */
  scrollable?: boolean;
  /** href of the current page — the exactly matching row gets `aria-current="page"` and the active treatment. */
  currentHref?: string;
  /** Controlled list of expanded item ids. */
  expandedIds?: string[];
  /**
   * Initially expanded item ids (uncontrolled). The branch and the
   * collapsible section that hold the current page start open as well, so a
   * reader landing deep in a long tree sees where they are.
   */
  defaultExpandedIds?: string[];
  /** Fires with the full new list of expanded ids whenever a toggle is pressed, in both controlled and uncontrolled modes. */
  onExpandedChange?: (expandedIds: string[]) => void;
  /** Allow several branches expanded at once. Default false: expanding one collapses its siblings, never the section or the rows it sits in. */
  multiple?: boolean;
  /** Fires when any link is clicked, alongside native navigation — e.g. to close the drawer that contains the list. */
  onNavigate?: (item: NavListItem, event: React.MouseEvent<HTMLElement>) => void;
  /** Accessible name of a collapsed row's or section's toggle, given its label. Defaults to "Expand <label>". */
  expandLabel?: (label: string) => string;
  /** Accessible name of an expanded row's or section's toggle, given its label. Defaults to "Collapse <label>". */
  collapseLabel?: (label: string) => string;
  /**
   * The component its links render with, such as Next.js's `Link`, so they
   * navigate through the app's router; passed on to each row's Button. Wins over a
   * LinkProvider's; a plain `<a>` when neither is set.
   */
  linkComponent?: LinkComponent;
  /** Additional CSS classes */
  className?: string;
};

export interface NavListProps
  extends NavListOwnProps,
    Omit<React.ComponentPropsWithoutRef<'ul'>, keyof NavListOwnProps> {}

const MAX_DEPTH = 3;

/**
 * Vertical list of navigation links for drawers and side menus.
 *
 * Every row is a real link, rendered as a tertiary Button so shape, sizing,
 * and interaction states stay identical to every other button in the system.
 * An item with children gets a separate chevron toggle — tapping the label
 * navigates, tapping the chevron expands — and collapsed sublists are `inert`,
 * so they leave the tab order and the accessibility tree. Expansion is
 * uncontrolled by default (`defaultExpandedIds`) or controlled via
 * `expandedIds` + `onExpandedChange`.
 */
export const NavList = React.forwardRef<HTMLUListElement, NavListProps>(
  (
    {
      items,
      size = 'default',
      scrollable = false,
      currentHref,
      expandedIds,
      defaultExpandedIds,
      onExpandedChange,
      multiple = false,
      onNavigate,
      expandLabel = (label) => `Expand ${label}`,
      collapseLabel = (label) => `Collapse ${label}`,
      linkComponent,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-nav-list';
    const uid = useId();

    const itemId = (item: NavListItem) => item.id ?? item.href;
    const sectionId = (section: NavListSection) => `section:${section.id ?? section.label}`;

    // Uncontrolled, the branch that holds the current page starts open, so
    // a reader landing deep in a long tree sees where they are.
    const [internalExpanded, setInternalExpanded] = useState<string[]>(() => {
      const open = new Set(defaultExpandedIds ?? []);
      const holdsCurrent = (item: NavListItem): boolean =>
        (item.current ?? (currentHref !== undefined && item.href === currentHref)) ||
        Boolean(item.items?.some(holdsCurrent));
      const walk = (list: NavListItem[]) => {
        for (const item of list) {
          if (item.items?.some(holdsCurrent)) open.add(itemId(item));
          if (item.items) walk(item.items);
        }
      };
      for (const entry of items) {
        if (isSection(entry)) {
          if (entry.collapsible && entry.items.some(holdsCurrent)) open.add(sectionId(entry));
          walk(entry.items);
        } else {
          walk([entry]);
        }
      }
      return [...open];
    });
    const expanded = expandedIds ?? internalExpanded;
    const rootRef = useRef<HTMLUListElement | null>(null);
    const setRootRef = (node: HTMLUListElement | null) => {
      rootRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // A scrollable list keeps its scrollbar out of sight until it scrolls,
    // and fades its content out at whichever end has more to scroll to.
    // Written straight to the DOM (data attributes), never React state, so
    // a scroll re-renders nothing.
    useEffect(() => {
      const root = rootRef.current;
      if (!scrollable || !root) return;
      let settle: ReturnType<typeof setTimeout> | undefined;
      const edges = () => {
        const max = root.scrollHeight - root.clientHeight;
        root.toggleAttribute('data-fade-start', root.scrollTop > 1);
        root.toggleAttribute('data-fade-end', root.scrollTop < max - 1);
      };
      const onScroll = () => {
        edges();
        root.setAttribute('data-scrolling', '');
        clearTimeout(settle);
        settle = setTimeout(() => root.removeAttribute('data-scrolling'), MOTION_SCROLL_SETTLE_MS);
      };
      edges();
      root.addEventListener('scroll', onScroll, { passive: true });
      const resize = new ResizeObserver(edges);
      resize.observe(root);
      return () => {
        clearTimeout(settle);
        root.removeEventListener('scroll', onScroll);
        resize.disconnect();
      };
    }, [scrollable]);

    // A scrollable list brings the current row into view once, on mount,
    // scrolling only itself: never the page around it.
    useEffect(() => {
      const root = rootRef.current;
      if (!scrollable || !root) return;
      const row = root.querySelector<HTMLElement>('[aria-current="page"]');
      if (!row) return;
      const top = row.getBoundingClientRect().top - root.getBoundingClientRect().top;
      if (top < 0 || top > root.clientHeight - row.offsetHeight) {
        root.scrollTop += top - root.clientHeight / 3;
      }
      // Mount only: later navigation is the reader's own scroll.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Each expandable id's ancestors (the rows and the section it sits in),
    // so the one-open rule closes only siblings, never the branch around
    // the row the reader just opened.
    const ancestorsOf = new Map<string, string[]>();
    const mapAncestors = (list: NavListItem[], chain: string[]) => {
      for (const item of list) {
        if (!item.items) continue;
        ancestorsOf.set(itemId(item), chain);
        mapAncestors(item.items, [...chain, itemId(item)]);
      }
    };
    for (const entry of items) {
      if (isSection(entry)) {
        ancestorsOf.set(sectionId(entry), []);
        mapAncestors(entry.items, [sectionId(entry)]);
      } else {
        mapAncestors([entry], []);
      }
    }

    const toggle = (id: string) => {
      // One open at a time among siblings only: an entry closes when it shares
      // the opened one's parent and kind (a section, or a row), so the branch
      // around it, its own open descendants and the rows of other sections
      // all stay as they are.
      const parentOf = (entry: string) => (ancestorsOf.get(entry) ?? []).join('\u0000');
      const isSection = (entry: string) => entry.startsWith('section:');
      const sibling = (entry: string) => parentOf(entry) === parentOf(id) && isSection(entry) === isSection(id);
      const next = expanded.includes(id)
        ? expanded.filter((entry) => entry !== id)
        : multiple
          ? [...expanded, id]
          : [...expanded.filter((entry) => !sibling(entry)), id];
      if (expandedIds === undefined) setInternalExpanded(next);
      onExpandedChange?.(next);
    };

    const renderItems = (level: number, levelItems: NavListItem[]) =>
      levelItems.map((item) => {
        const id = itemId(item);
        const isCurrent = item.current ?? (currentHref !== undefined && item.href === currentHref);
        const children = level < MAX_DEPTH ? item.items : undefined;
        const collapsible = item.collapsible ?? true;
        const isOpen = expanded.includes(id);
        const panelId = `${uid}-${id}`;

        const link = (
          <Button
            variant="tertiary"
            size={level === 1 && size === 'default' ? 'default' : 'compact'}
            label={item.label}
            iconRight={item.badge ? <Badge className={`${baseClass}__badge`} label={item.badge} variant="neutral" /> : undefined}
            href={item.href}
            linkComponent={linkComponent}
            ariaCurrent={isCurrent}
            className={isCurrent ? 'ds-button--active' : undefined}
            onClick={(event) => onNavigate?.(item, event)}
          />
        );

        if (!children || children.length === 0) {
          return (
            <li key={id} className={`${baseClass}__item`}>
              {link}
            </li>
          );
        }

        if (!collapsible) {
          return (
            <li key={id} className={`${baseClass}__item`}>
              {link}
              <ul className={`${baseClass}__sublist`}>{renderItems(level + 1, children)}</ul>
            </li>
          );
        }

        return (
          <li key={id} className={`${baseClass}__item`}>
            <div className={`${baseClass}__row`}>
              {link}
              <button
                type="button"
                className={`${baseClass}__toggle`}
                aria-expanded={isOpen}
                aria-controls={panelId}
                aria-label={isOpen ? collapseLabel(item.label) : expandLabel(item.label)}
                onClick={() => toggle(id)}
              >
                <span
                  className={`${baseClass}__chevron material-symbols-rounded`}
                  aria-hidden="true"
                >
                  expand_more
                </span>
              </button>
            </div>
            <div
              id={panelId}
              className={`${baseClass}__panel ${isOpen ? `${baseClass}__panel--open` : ''}`}
              inert={!isOpen}
            >
              <ul className={`${baseClass}__sublist`}>{renderItems(level + 1, children)}</ul>
            </div>
          </li>
        );
      });

    const renderSection = (section: NavListSection) => {
      const id = sectionId(section);
      const panelId = `${uid}-${id}`;
      const isOpen = !section.collapsible || expanded.includes(id);
      return (
        <li key={id} className={`${baseClass}__section`}>
          {section.collapsible ? (
            <button
              type="button"
              className={`${baseClass}__heading ${baseClass}__heading--toggle`}
              aria-expanded={isOpen}
              aria-controls={panelId}
              aria-label={isOpen ? collapseLabel(section.label) : expandLabel(section.label)}
              onClick={() => toggle(id)}
            >
              <span className={`${baseClass}__heading-text`}>{section.label}</span>
              <span className={`${baseClass}__chevron material-symbols-rounded`} aria-hidden="true">
                expand_more
              </span>
            </button>
          ) : (
            <span className={`${baseClass}__heading`} id={`${panelId}-heading`}>
              {section.label}
            </span>
          )}
          <div
            id={panelId}
            className={`${baseClass}__panel ${isOpen ? `${baseClass}__panel--open` : ''}`}
            inert={!isOpen}
          >
            <ul
              className={`${baseClass}__section-list`}
              aria-labelledby={section.collapsible ? undefined : `${panelId}-heading`}
              aria-label={section.collapsible ? section.label : undefined}
            >
              {renderItems(1, section.items)}
            </ul>
          </div>
        </li>
      );
    };

    const classes = [
      baseClass,
      size === 'compact' ? `${baseClass}--compact` : '',
      scrollable ? `${baseClass}--scrollable` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <ul {...rest} ref={setRootRef} className={classes}>
        {items.map((entry) => (isSection(entry) ? renderSection(entry) : renderItems(1, [entry])))}
      </ul>
    );
  },
);

NavList.displayName = 'NavList';
